{"path":"assets/css/styles.css","content":"/* Bold Playful theme — premium, geometric, accessible */
:root{
  --bg:#fff;
  --muted:#6b6b6b;
  --accent:#ff7a59;
  --accent-2:#ffd166;
  --dark:#0b1320;
  --card:#fff7f3;
  --radius:12px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{font-family:system-ui,-apple-system,'Segoe UI',Roboto,'Helvetica Neue',Arial;line-height:1.5;color:var(--dark);background:var(--bg);margin:0}
.container{max-width:1100px;margin:0 auto;padding:28px}
.site-header{border-bottom:1px solid rgba(11,19,32,0.06);background:linear-gradient(90deg, rgba(255,122,89,0.03), rgba(255,209,102,0.02));position:sticky;top:0;z-index:20}
.site-header .container{display:flex;align-items:center;justify-content:space-between}
.brand{display:flex;align-items:center;gap:12px;text-decoration:none;color:var(--dark)}
.logo-pattern{width:44px;height:44px}
.business{font-weight:700;font-size:18px}
.nav ul{display:flex;gap:14px;list-style:none;padding:0;margin:0}
.nav a{color:var(--muted);text-decoration:none;padding:8px 10px;border-radius:8px}
.nav a:hover{color:var(--dark);background:rgba(11,19,32,0.03)}
.cta-link{background:var(--accent);color:white;padding:8px 12px;border-radius:10px}
.hero{padding:48px 0}
.hero-grid{display:grid;grid-template-columns:1fr 360px;gap:28px;align-items:center}
.hero-copy h1{font-size:40px;margin:0 0 10px;color:var(--dark)}
.lead{color:var(--muted);margin-bottom:18px}
.hero-cta{display:flex;gap:12px;margin-bottom:18px}
.btn{border:0;padding:10px 16px;border-radius:10px;font-weight:600;cursor:pointer}
.btn.primary{background:var(--accent);color:white}
.btn.outline{background:transparent;border:2px solid rgba(11,19,32,0.06)}
.btn.large{padding:14px 20px;font-size:16px}
.quick-meta{display:flex;gap:12px list-style:none;padding:0;margin:0;color:var(--muted);font-size:14px}
.hero-art img{width:100%;height:auto;display:block}
.story, .framework, .programs, .pricing, .testimonials, .cta{padding:36px 0}
.story h2, .framework h2, .programs h2, .pricing h2, .testimonials h2, .cta h2{font-size:22px;margin-bottom:10px}
.note{font-size:13px;color:var(--muted);margin-top:8px}
.tracks{display:flex;gap:18px;margin-top:12px}
.card{background:linear-gradient(180deg,var(--card),#fff);padding:18px;border-radius:12px;box-shadow:0 6px 18px rgba(11,19,32,0.06);flex:1}
.program-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:16px}
.program{background:rgba(255,250,245,0.7);padding:16px;border-radius:10px}
.pricing-grid{display:flex;gap:12px;margin-top:12px}
.price-card{background:linear-gradient(90deg, rgba(255,122,89,0.06), rgba(255,209,102,0.04));padding:16px;border-radius:12px;flex:1}
.price{font-weight:700;font-size:18px;margin:6px 0}
.test-grid{display:flex;gap:12px}
blockquote{background:#fff;padding:14px;border-radius:10px;box-shadow:0 6px 16px rgba(11,19,32,0.04);flex:1}
cite{display:block;margin-top:8px;color:var(--muted);font-size:13px}
.site-footer{border-top:1px solid rgba(11,19,32,0.06);padding:28px 0;background:linear-gradient(180deg,#fff,#fff7f3)}
.footer-grid{display:grid;grid-template-columns:1fr 1fr 220px;gap:18px}
.small{font-size:13px;color:var(--muted)}
.disclaimer{font-size:12px;color:var(--muted);margin-top:12px}
.modal{position:fixed;inset:0;background:rgba(11,19,32,0.45);display:none;align-items:center;justify-content:center;padding:20px}
.modal[aria-hidden="false"]{display:flex}
.modal-panel{background:white;padding:20px;border-radius:12px;max-width:480px;width:100%;position:relative}
.modal-close{position:absolute;right:10px;top:10px;border:0;background:transparent;font-size:20px}
form label{display:block;margin-bottom:10px;font-size:14px}
form input, form textarea{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(11,19,32,0.08)}
.form-actions{display:flex;gap:8px;justify-content:flex-end;margin-top:8px}
.privacy-small{font-size:12px;color:var(--muted);margin-top:8px}
@media(max-width:880px){
  .hero-grid{grid-template-columns:1fr;}
  .program-grid{grid-template-columns:1fr}
  .pricing-grid{flex-direction:column}
  .tracks{flex-direction:column}
  .footer-grid{grid-template-columns:1fr}
}
"}
{"path":"assets/js/main.js","content":"(function(){
  var open = document.getElementById('open-modal');
  var modal = document.getElementById('modal');
  var close = document.getElementById('close-modal');
  var cancel = document.getElementById('cancel-modal');
  var form = document.getElementById('consult-form');

  function showModal(){
    modal.setAttribute('aria-hidden','false');
    document.body.style.overflow = 'hidden';
  }
  function hideModal(){
    modal.setAttribute('aria-hidden','true');
    document.body.style.overflow = '';
  }
  if(open) open.addEventListener('click', showModal);
  if(close) close.addEventListener('click', hideModal);
  if(cancel) cancel.addEventListener('click', hideModal);
  modal.addEventListener('click', function(e){ if(e.target===modal) hideModal(); });

  if(form){
    form.addEventListener('submit', function(e){
      e.preventDefault();
      var btn = form.querySelector('button[type="submit"]');
      btn.disabled = true; btn.textContent = 'Sending...';
      setTimeout(function(){
        btn.textContent = 'Sent';
        form.reset();
        setTimeout(function(){ btn.disabled=false; btn.textContent='Send'; hideModal(); }, 900);
      },900);
    });
  }

  // Small accessibility helper: close on Escape
  document.addEventListener('keydown', function(e){ if(e.key==='Escape'){ hideModal(); } });
})();"}
